// ---- lib/match.js
// Choix automatique du produit. Collé tel quel en tête des nodes Code n8n (voir scripts/bundle.mjs).
const ACCESSORY_RE = /sleeve|pochette|sticker|autocollant|\bkit\b|feuille de score|piste de suivi|figurine|\bsacs?\b|insert|organiseur|playmat|tapis de jeu|goodies/i;

// Accents combinants (plage U+0300 a U+036F) : construits sans echappement unicode, que n8n transforme a l enregistrement.
const COMBINING_RE = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');

function normalize(s) {
  return String(s || '')
    .normalize('NFD').replace(COMBINING_RE, '')
    .toLowerCase()
    .replace(/\((vf|vo|fr|en|version francaise|version anglaise)\)/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function isAccessory(title) {
  return ACCESSORY_RE.test(title || '');
}

// Vrai si a et b sont égaux à une insertion, suppression ou substitution près.
function within1(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  if (a.length === b.length) return a.slice(i + 1) === b.slice(i + 1);
  return a.length > b.length ? a.slice(i + 1) === b.slice(i) : b.slice(i + 1) === a.slice(i);
}

// Distance d'édition (insertions, suppressions, substitutions) entre deux chaînes.
function distance(a, b) {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[b.length];
}

// Pluriel ignoré mot par mot (« mots malins » = « mot malin ») ; mots de 3 lettres et moins intacts.
const singulier = t => t.split(' ').map(w => (w.length > 3 ? w.replace(/[sx]$/, '') : w));

// Ordre de préférence : titre exact → titre à une lettre près (« catane » → « Catan ») →
// titres contenant tous les mots (pluriels ignorés), jeu de base avant extension, dans l'ordre de pertinence du site →
// en dernier recours, titre à 2 lettres près si la recherche fait au moins 8 caractères.
// Les lettres d'écart sont dans les mots, jamais sur les espaces (même nombre de mots) : « el dorado » ≠ « Eldorado ».
const memesMots = (a, b) => a.split(' ').length === b.split(' ').length;
function pickProduct(query, candidates) {
  const q = normalize(query);
  const pool = (candidates || []).filter(c => c && c.title && !isAccessory(c.title));
  if (!q || pool.length === 0) return null;
  const frFirst = (a, b) => (a.lang === 'fr' ? 0 : 1) - (b.lang === 'fr' ? 0 : 1);
  const exact = pool.filter(c => normalize(c.title) === q).sort(frFirst);
  if (exact.length) return exact[0];
  if (q.length >= 5) {
    const near = pool.filter(c => { const t = normalize(c.title); return memesMots(t, q) && within1(t, q); }).sort(frFirst);
    if (near.length) return near[0];
  }
  const words = singulier(q);
  const all = pool.filter(c => { const t = ` ${singulier(normalize(c.title)).join(' ')} `; return words.every(w => t.includes(` ${w} `)); });
  const isExt = c => /\bext(ension)?\b/.test(normalize(c.title));
  const base = /\bext(ension)?\b/.test(q) ? all : all.filter(c => !isExt(c));
  const best = [...(base.length ? base : all)].sort(frFirst)[0];
  if (best) return best;
  if (q.length < 8) return null;
  const proches = pool.filter(c => { const t = normalize(c.title); return memesMots(t, q) && distance(t, q) <= 2; }).sort(frFirst);
  return proches[0] || null;
}

// Recherches à tenter sur un site qui ne cherche que le titre exact (Okkazeo) : telle quelle, puis au singulier
// (« mots malins » : Okkazeo ne trouve « Mot Malin » qu'avec « mot malin »).
function variantesRecherche(q) {
  const n = normalize(q);
  const s = singulier(n).join(' ');
  return s && s !== n ? [q, s] : [q];
}

if (typeof module !== 'undefined' && module.exports) module.exports = { normalize, isAccessory, pickProduct, variantesRecherche };


// ---- lib/sites.js
// Parseurs des pages de recherche (structure observée le 2026-10-13, voir docs/sources.md).
// Pas de `URL` dans le bac à sable des nodes Code n8n (vérifié le 2026-10-13) : résolution à la main.
function absUrl(base, href) {
  const h = String(href || '').trim();
  if (!h) return null;
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return 'https:' + h;
  const origin = (String(base).match(/^https?:\/\/[^/]+/i) || [])[0];
  if (!origin) return null;
  return origin + (h.startsWith('/') ? h : '/' + h);
}

function clean(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&#x27;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

// Philibert : une carte = <div class="product-card … " data-pid="…">, titre dans a.product-card__title,
// langue dans span.product-card__feature, note « x/5 » avant le titre si le produit a des avis.
function parsePhilibertSearch(html) {
  const out = [];
  for (const card of String(html || '').split(/(?=<div\s+class="product-card\s[^"]*"\s+data-pid=)/).slice(1)) {
    const a = card.match(/<a class="h6 mb-0 product-card__title[^"]*" href="([^"]+)">([^<]+)<\/a>/);
    if (!a) continue;
    const features = [...card.matchAll(/<span class="product-card__feature">([^<]*)<\/span>/g)].map(m => clean(m[1]));
    const lang = features.includes('Français') ? 'fr' : features.includes('Anglais') ? 'en' : undefined;
    const n = clean(card.slice(0, a.index)).match(/(\d(?:[.,]\d)?)\/5/);
    out.push({
      title: clean(a[2]),
      url: absUrl('https://www.philibertnet.com/', a[1]),
      lang,
      note: n ? parseFloat(n[1].replace(',', '.')) : null,
    });
  }
  return out;
}

// Esprit Jeu : <h3 class="bp_designation"><a href="…"> Titre </a></h3>
function parseEspritJeuSearch(html) {
  return [...String(html || '').matchAll(/<h3 class="bp_designation">\s*<a href="([^"]+)">\s*([^<]*?)\s*<\/a>/g)]
    .map(m => ({ title: clean(m[2]), url: absUrl('https://www.espritjeu.com/', m[1]) }))
    .filter(c => c.title && c.url);
}

// Okkazeo : un résultat = <article class="… jeu …"> avec <h4 class="titre"><a href="/jeux/<id>/<slug>">Titre</a></h4>
// et <b>N annonces</b> (nombre d'annonces de cette édition ; null si absent).
function parseOkkazeoSearch(html) {
  const out = [];
  for (const art of String(html || '').split(/(?=<article class="grid-x box_article jeu)/).slice(1)) {
    const a = art.match(/<h4 class="titre"><a href="(\/jeux\/\d+\/[^"]*)"[^>]*>([^<]*)<\/a>/);
    if (!a) continue;
    const n = art.match(/<b>\s*(\d+)\s+annonces?\s*<\/b>/);
    const c = { title: clean(a[2]), url: absUrl('https://www.okkazeo.com/', a[1]), annonces: n ? Number(n[1]) : null };
    if (c.title && c.url) out.push(c);
  }
  return out;
}

if (typeof module !== 'undefined' && module.exports) module.exports = { parsePhilibertSearch, parseEspritJeuSearch, parseOkkazeoSearch };


// ---- lib/myludo.js
// MyLudo : application JavaScript, API interne views/search/datas.php et views/game/datas.php (voir docs/sources.md).
function myludoUrl(g) { return `https://www.myludo.fr/#!/game/${g.code}-${g.id}`; }

function parseMyludoSearch(json) {
  return ((json && json.list) || [])
    .filter(g => g && g.id && g.title)
    .map(g => ({ title: String(g.title).trim(), id: String(g.id), type: g.type || 'basegame', url: myludoUrl(g) }));
}

// Jeu de base d'abord : une extension n'est choisie que si aucun jeu de base ne correspond à la requête.
function pickMyludo(query, candidates) {
  return pickProduct(query, candidates.filter(c => c.type === 'basegame')) || pickProduct(query, candidates);
}

// Fiche : note de la communauté (sur 10) + infos pratiques. rating.game.note = « 8,3 », audience = nombre de notes.
const frNum = v => { const n = parseFloat(String(v).replace(",", ".")); return Number.isFinite(n) ? n : null; };
function parseMyludoGame(g) {
  const r = g && g.rating && g.rating.game;
  const c = g && g.rating && g.rating.complexity;
  const has = !!(r && r.audience > 0);
  const note = has ? frNum(r.note ?? r.weighted ?? r.average) : null;
  const tmin = frNum(g.time_min), tmax = frNum(g.time_max);
  const duree = tmin && tmax && tmin !== tmax ? tmin + "–" + tmax : (tmin || tmax || frNum(g.duration));
  return {
    note, avis: has ? r.audience : null, titre: g.title, url: myludoUrl(g),
    image: (g.image && (g.image.S160 || g.image.S300)) || null,
    annee: g.edition || null, joueurs: g.players || null, age: g.age || null, duree: duree || null,
    complexite: c && c.audience > 0 ? frNum(c.note) : null,
  };
}

// Fiche détaillée (type=info) : themes.mecanisme = { "deck-building-22": "Deck building", ... } → id du tag en fin de clé.
function parseMyludoInfo(info) {
  const t = (info && info.themes) || {};
  const tags = o => Object.entries(o || {}).map(([slug, nom]) => ({ id: (slug.match(/-(\d+)$/) || [])[1], nom: String(nom) })).filter(x => x.id);
  const auteurs = Object.values((info && info.people) || {}).filter(p => p && p.id && (p.roles || []).includes('Auteur')).map(p => ({ id: String(p.id), nom: String(p.title) }));
  return { mecaniques: tags(t.mecanisme), themes: tags(t.theme).map(x => x.nom), auteurs };
}

// tagLists : [{ id, nom, count, list }] (list = jeux de base du tag, du mieux classé au moins bien).
// Mécaniques principales = les plus rares (les plus distinctives), pas les plus répandues (« Exploration »).
function topMecaniques(tagLists, n = 5) {
  return [...tagLists].sort((a, b) => a.count - b.count).slice(0, n).map(t => t.nom);
}

// Jeux du même auteur (people/datas.php?type=games, tous rôles confondus, non triable par notoriété) : jeux de base seulement,
// sans le jeu ni sa gamme, un titre une seule fois (édition la plus récente). Les plus connus d'abord = les plus réédités
// (éditions et traductions sont des entrées distinctes), puis ceux déjà classés dans les listes de mécaniques du jeu
// (populaires : titres normalisés). Pas de lecture des fiches (≈ 1 s chacune côté MyLudo).
function pickAuteurJeux(titre, list, populaires = new Set(), n = 7) {
  const base = normalize(titre);
  const groupes = new Map();
  for (const g of list || []) {
    if (!g || g.type !== 'basegame') continue;
    const k = normalize(g.title);
    if (!k || k === base || k.startsWith(base + ' ') || base.startsWith(k + ' ')) continue;
    if (!groupes.has(k)) groupes.set(k, []);
    groupes.get(k).push(g);
  }
  return [...groupes.entries()]
    .map(([k, gs]) => ({ pop: populaires.has(k) ? 1 : 0, n: gs.length, g: gs.reduce((a, b) => ((b.edition || 0) > (a.edition || 0) ? b : a)) }))
    .sort((a, b) => b.n - a.n || b.pop - a.pop)
    .slice(0, n)
    .map(({ g }) => ({ id: g.id, titre: g.title, annee: g.edition || null, url: myludoUrl(g) }));
}

if (typeof module !== 'undefined' && module.exports) {
  if (typeof pickProduct === 'undefined') global.pickProduct = require('./match.js').pickProduct;
  if (typeof normalize === 'undefined') global.normalize = require('./match.js').normalize;
  module.exports = { parseMyludoSearch, pickMyludo, parseMyludoGame, parseMyludoInfo, topMecaniques, pickAuteurJeux };
}


