// ---- lib/bgg.js
// BGG xmlapi2 (recherche + fiche). Dépend de normalize() (lib/match.js, chargé avant dans les nodes n8n).
function bggDecode(s) { return String(s).replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>'); }
function bggAttr(tag, name) { const m = String(tag).match(new RegExp(`\\b${name}="([^"]*)"`)); return m ? bggDecode(m[1]) : null; }
function bggVal(body, tag) { const m = String(body).match(new RegExp(`<${tag}\\b[^>]*\\bvalue="([^"]*)"`)); return m ? m[1] : null; }

function parseBggSearch(xml) {
  return [...String(xml || '').matchAll(/<item\b([^>]*)>([\s\S]*?)<\/item>/g)].map(([, a, body]) => {
    const nom = (body.match(/<name\b[^>]*>/) || [''])[0];
    return { id: bggAttr(a, 'id'), type: bggAttr(a, 'type'), name: bggAttr(nom, 'value'), primaire: bggAttr(nom, 'type') === 'primary' };
  });
}

// Candidats, du plus probable au moins probable (20 au plus, limite de l'API thing) :
// nom exact, puis jeux dont le nom de base (avant « : » ou « - ») est la recherche (« Clank!: A Deck-Building Adventure »),
// sinon tous les mots (titres les plus courts d'abord : BGG renvoie ses 120 résultats dans le désordre).
function bggCandidates(query, items) {
  const q = normalize(query);
  if (!q) return [];
  const nom = i => String(i.name || '');
  // Un nom principal exact écarte les jeux qui n'ont ce nom qu'en alternatif (pickBgg garderait le plus voté :
  // « El Dorado » donnait Eldorado, alias El Dorado).
  const exactTous = items.filter(i => normalize(nom(i)) === q);
  const principal = exactTous.some(i => i.primaire);
  const exact = principal ? exactTous.filter(i => i.primaire) : exactTous;
  const base = items.filter(i => i.type === 'boardgame' && (!principal || i.primaire) && normalize(nom(i).split(/:| - /)[0]) === q);
  let hit = [...exact, ...base];
  if (!hit.length) {
    const words = q.split(' ');
    hit = items.filter(i => { const t = ` ${normalize(nom(i))} `; return words.every(w => t.includes(` ${w} `)); })
      .sort((x, y) => nom(x).length - nom(y).length);
  }
  return [...new Set(hit.map(i => i.id))].slice(0, 20);
}

function parseBggThings(xml) {
  return [...String(xml || '').matchAll(/<item\b([^>]*)>([\s\S]*?)<\/item>/g)].map(([, a, b]) => {
    // BGG met value="0" pour « inconnu » (jeu récent) : 0 n'est jamais une donnée, sauf le nombre de votes.
    const n = (k, zeroOk) => { const v = bggVal(b, k); return v == null || v === '' || (!zeroOk && Number(v) === 0) ? null : Number(v); };
    const primary = (b.match(/<name\b[^>]*type="primary"[^>]*>/) || [''])[0];
    const liens = type => [...b.matchAll(/<link\b[^>]*>/g)].map(m => m[0]).filter(l => bggAttr(l, 'type') === type)
      .map(l => ({ id: bggAttr(l, 'id'), nom: bggAttr(l, 'value') })).filter(l => l.nom);
    // Rangs : général (subtype boardgame) et par famille (stratégie, famille, ambiance…) ; « Not Ranked » ignoré.
    const rangs = [...b.matchAll(/<rank\b[^>]*>/g)].map(m => ({ type: bggAttr(m[0], 'type'), nom: bggAttr(m[0], 'name'), rang: Number(bggAttr(m[0], 'value')) }))
      .filter(r => Number.isInteger(r.rang) && r.rang > 0);
    // Sondage « meilleur nombre de joueurs » : « Best with 3–4 players » → « 3–4 ».
    const best = (b.match(/<result name="bestwith" value="([^"]*)"/) || [])[1];
    return {
      id: bggAttr(a, 'id'), type: bggAttr(a, 'type'), titre: bggAttr(primary, 'value'),
      image: ((b.match(/<image>([^<]*)<\/image>/) || [])[1] || '').trim() || null,
      annee: n('yearpublished'), minp: n('minplayers'), maxp: n('maxplayers'),
      mint: n('minplaytime'), maxt: n('maxplaytime'), age: n('minage'),
      votes: n('usersrated', true), average: n('average'), poids: n('averageweight'),
      mecaniques: liens('boardgamemechanic'), categories: liens('boardgamecategory'), extensions: liens('boardgameexpansion').length,
      rang: (rangs.find(r => r.type === 'subtype' && r.nom === 'boardgame') || {}).rang || null,
      rangsFamille: rangs.filter(r => r.type === 'family'),
      ideal: best ? bggDecode(best).replace(/^Best with\s*/i, '').replace(/\s*players?$/i, '').trim() || null : null,
    };
  });
}

// Libellé BGG (mécanique, catégorie) en français (lib/bgg-fr.js), sans tenir compte des espaces ni de la ponctuation
// (BGG écrit « Spies / Secret Agents » et « Murder/Mystery ») ; inconnu → gardé en anglais.
const bggCle = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '');
let BGG_FR_TABLE = null;
function bggFr(label) {
  if (!BGG_FR_TABLE) BGG_FR_TABLE = new Map(Object.entries(BGG_FR).map(([k, v]) => [bggCle(k), v]));
  return BGG_FR_TABLE.get(bggCle(label)) || label;
}
// Classements BGG par famille (name de <rank type="family">).
const BGG_RANG_FR = { strategygames: 'stratégie', familygames: 'famille', partygames: 'ambiance', thematic: 'thématique', abstracts: 'abstrait', wargames: 'wargame', childrensgames: 'enfants', cgs: 'cartes à collectionner' };

function bggRange(a, b) { return a == null ? null : (b == null || a === b ? String(a) : `${a}–${b}`); }

function pickBgg(things) {
  const t = [...(things || [])].sort((x, y) => (x.type === 'boardgame' ? 0 : 1) - (y.type === 'boardgame' ? 0 : 1) || (y.votes || 0) - (x.votes || 0))[0];
  if (!t) return null;
  const r1 = v => (v == null ? null : Math.round(v * 10) / 10);
  // Style de jeu en français : toutes les mécaniques (10 max, avec leur id BGG pour le top de la mécanique),
  // complétées par les catégories pour en avoir au moins 7.
  const mecaniques = [];
  for (const m of t.mecaniques || []) {
    const nom = bggFr(m.nom);
    if (mecaniques.length < 10 && !mecaniques.some(x => x.nom === nom)) mecaniques.push({ id: m.id, nom });
  }
  const themes = [...new Set((t.categories || []).map(c => bggFr(c.nom)))].filter(x => !mecaniques.some(m => m.nom === x))
    .slice(0, Math.max(3, 7 - mecaniques.length));
  // Catégorie principale = la famille où le jeu est le mieux classé.
  const fam = [...(t.rangsFamille || [])].sort((a, b) => a.rang - b.rang)[0];
  return {
    id: t.id, note: r1(t.average), votes: t.votes, duree: bggRange(t.mint, t.maxt),
    poids: t.poids == null ? null : Math.round(t.poids * 100) / 100, titre: t.titre,
    annee: t.annee, joueurs: bggRange(t.minp, t.maxp), age: t.age == null ? null : `${t.age}+`,
    image: t.image, url: `https://boardgamegeek.com/boardgame/${t.id}`, mecaniques, themes,
    rang: t.rang || null, rangCat: fam ? { rang: fam.rang, nom: BGG_RANG_FR[fam.nom] || fam.nom } : null,
    ideal: t.ideal || null, extensions: t.extensions || 0,
  };
}

// Jeux similaires = recommandations des joueurs BGG (« si tu aimes X, essaie Y ») : api.geekdo.com/api/geekitem/recs,
// sans token, point d'accès interne (non officiel). Exclus : le jeu et sa gamme (même nom de base, avant « : »), doublons
// (« Ticket to Ride » y figure deux fois). La note, le nombre de votes et le rang sont fournis : aucune fiche à lire.
function pickBggRecs(json, titre, n = 5) {
  const nomBase = t => normalize(String(t || '').split(/:| - /)[0]);
  const base = nomBase(titre);
  const vus = new Set();
  const out = [];
  for (const r of (json && json.recs) || []) {
    const it = r && r.item;
    if (!it || !it.id || !it.name) continue;
    const k = nomBase(it.name);
    if (!k || vus.has(k) || (base && (k === base || k.startsWith(base + ' ') || base.startsWith(k + ' ')))) continue;
    vus.add(k);
    out.push({
      id: String(it.id), titre: it.name, annee: Number(r.yearpublished) || null,
      url: 'https://boardgamegeek.com' + (it.href || '/boardgame/' + it.id),
      note: r.rating ? Math.round(r.rating * 10) / 10 : null, avis: r.numvoters ?? null, rang: r.rank || null,
    });
    if (out.length >= n) break;
  }
  return out;
}

// Version duo (2 joueurs) d'un jeu, d'après les fiches geekitems de BGG (point d'accès interne, sans token) :
// candidats = jeux « Integrates with » et « Reimplemented by » du jeu ; duo = famille « Two-Player Versions of More-Player Games »
// (Res Arcana Duo, Wingspan Asia : le nombre de joueurs ne suffit pas, Asia est noté 1-7 car combinable).
// integrable = le duo est dans « Integrates with » : ses cartes s'ajoutent au jeu de base.
function duoCandidats(base) {
  const l = (base && base.links) || {};
  const integ = (l.boardgameintegration || []).map(x => String(x.objectid));
  return { integ, ids: [...new Set([...integ, ...(l.reimplementation || []).map(x => String(x.objectid))])].slice(0, 6) };
}
function pickDuo(base, fiches) {
  if (!base || Number(base.maxplayers) <= 2) return null; // jeu déjà à 2 : pas de duo
  const { integ } = duoCandidats(base);
  const duos = (fiches || []).filter(f => f && ((f.links && f.links.boardgamefamily) || []).some(x => /two-player versions of more-player games/i.test(x.name)));
  const d = duos.find(f => integ.includes(String(f.objectid))) || duos[0];
  return d ? { titre: d.name, url: 'https://boardgamegeek.com' + (d.href || '/boardgame/' + d.objectid), integrable: integ.includes(String(d.objectid)) } : null;
}

if (typeof module !== 'undefined' && module.exports) {
  if (typeof normalize === 'undefined') global.normalize = require('./match.js').normalize;
  if (typeof BGG_FR === 'undefined') global.BGG_FR = require('./bgg-fr.js');
  module.exports = { parseBggSearch, bggCandidates, parseBggThings, pickBgg, pickBggRecs, bggFr, duoCandidats, pickDuo };
}


// ---- lib/outils.js
// Outils chargés au clic (workflow « Notes Jeux — Outils ») : extensions, top d'une mécanique, jumeaux.
// Sources : points d'accès internes BGG sans token, api.geekdo.com/api/geekitem/linkeditems et /api/geekitems (vérifiés le 2026-10-31).
// Dépend de normalize() (lib/match.js) et bggFr() (lib/bgg.js), chargés avant dans le node.

const BGG = 'https://boardgamegeek.com';
const num = v => { const n = Number(v); return Number.isFinite(n) && n > 0 ? n : null; };

// Liste linkeditems → jeux { id, titre, annee, note, votes, rang, poids, url }.
function parseLinkedItems(json) {
  return ((json && json.items) || []).filter(i => i && i.objectid && i.name).map(i => ({
    id: String(i.objectid), titre: i.name, annee: num(i.yearpublished), type: i.subtype || null,
    note: num(i.average) ? Math.round(num(i.average) * 10) / 10 : null, votes: Number(i.usersrated) || 0,
    rang: num(i.rank), poids: num(i.avgweight), url: BGG + (i.href || '/boardgame/' + i.objectid),
  }));
}

// Extensions d'un jeu : les plus jouées (votes) d'abord.
function pickExtensions(json, n = 30) {
  return parseLinkedItems(json).sort((a, b) => b.votes - a.votes).slice(0, n);
}

// Meilleurs jeux d'une mécanique : ordre du classement BGG (sort=rank), jeux classés seulement.
function pickTopMeca(json, n = 20) {
  return parseLinkedItems(json).filter(j => j.rang).slice(0, n);
}

// Fiche geekitems → étiquettes utiles à la ressemblance. Familles gardées : « Mechanism: » et « Theme: » seulement
// (les autres sont des séries, des éditeurs ou des adaptations numériques).
function geekItemTags(json) {
  const it = (json && json.item) || {};
  const l = it.links || {};
  const tags = (k, type) => (l[k] || []).filter(x => x && x.objectid && x.name).map(x => ({ id: String(x.objectid), nom: x.name, type }));
  return {
    id: String(it.objectid || ''), titre: it.name || '', type: it.subtype || null, annee: num(it.yearpublished),
    minp: num(it.minplayers), maxp: num(it.maxplayers), mint: num(it.minplaytime), maxt: num(it.maxplaytime),
    tags: [
      ...tags('boardgamemechanic', 'mecanique'),
      ...tags('boardgamefamily', 'famille').filter(t => /^Mechanism:/i.test(t.nom)),
      ...tags('boardgamefamily', 'theme').filter(t => /^Theme:/i.test(t.nom)),
      ...tags('boardgamecategory', 'categorie'),
    ],
  };
}

// Paramètres linkeditems d'une étiquette (mécanique et catégorie = « property », famille = « family »).
function linkedItemsUrl(tag, { index = 'boardgame', count = 50 } = {}) {
  const sub = { mecanique: 'boardgamemechanic', categorie: 'boardgamecategory', famille: 'boardgamefamily', theme: 'boardgamefamily' }[tag.type];
  const objtype = sub === 'boardgamefamily' ? 'family' : 'property';
  return `https://api.geekdo.com/api/geekitem/linkeditems?ajax=1&linkdata_index=${index}&nosession=1&objectid=${tag.id}&objecttype=${objtype}&pageid=1&showcount=${count}&sort=rank&subtype=${sub}`;
}

// Jumeaux : jeux qui partagent les étiquettes les plus RARES du jeu (rareté = log(N / nombre de jeux de l'étiquette)).
// listes : [{ tag, total, jeux }] (linkeditems de chaque étiquette du jeu) ; fiches : Map id → geekItemTags des finalistes.
const N_JEUX = 150000;
// Familles « Theme: » (Nature, Art…) : décor, pas mécanisme → même poids qu'une catégorie.
const POIDS_TYPE = { mecanique: 1, famille: 1, theme: 0.5, categorie: 0.5 };
const rarete = total => Math.log(N_JEUX / Math.max(1, total || 1));
const nomBaseJeu = t => normalize(String(t || '').split(/:| - /)[0]);

function preselection(cible, listes, n = 15) {
  const base = nomBaseJeu(cible.titre);
  const score = new Map();
  for (const { tag, total, jeux } of listes) {
    const w = rarete(total) * (POIDS_TYPE[tag.type] || 0);
    for (const j of jeux) {
      if (j.id === cible.id || (j.type && j.type !== 'boardgame')) continue;
      const k = nomBaseJeu(j.titre);
      if (!k || k === base || k.startsWith(base + ' ') || base.startsWith(k + ' ')) continue;
      const s = score.get(j.id) || { jeu: j, s: 0 };
      s.s += w;
      score.set(j.id, s);
    }
  }
  return [...score.values()].sort((a, b) => b.s - a.s).slice(0, n).map(x => x.jeu);
}

function libelleTag(t) { return bggFr(String(t.nom).replace(/^(Mechanism|Theme):\s*/i, '')); }

function scoreJumeaux(cible, listes, finalistes, fiches, n = 2) {
  const totaux = new Map(listes.map(l => [l.tag.id + l.tag.type, l.total]));
  const poidsTag = t => rarete(totaux.get(t.id + t.type)) * (POIDS_TYPE[t.type] || 0);
  const total = cible.tags.reduce((s, t) => s + poidsTag(t), 0) || 1;
  const moy = (a, b) => (a && b ? (a + b) / 2 : a || b || null);
  const out = [];
  for (const j of finalistes) {
    const f = fiches.get(j.id);
    if (!f) continue;
    const ids = new Set(f.tags.map(t => t.id + t.type));
    const communs = cible.tags.filter(t => ids.has(t.id + t.type));
    let s = communs.reduce((x, t) => x + poidsTag(t), 0) / total;
    // Pénalités : écart de poids (complexité), de durée, nombres de joueurs sans recouvrement.
    if (cible.poids && j.poids) s *= Math.exp(-Math.abs(cible.poids - j.poids) / 1.5);
    const d1 = moy(cible.mint, cible.maxt), d2 = moy(f.mint, f.maxt);
    if (d1 && d2) s *= 1 / (1 + 0.25 * Math.abs(Math.log(d1 / d2)));
    if (cible.minp && cible.maxp && f.minp && f.maxp && (f.maxp < cible.minp || f.minp > cible.maxp)) s *= 0.6;
    // À ressemblance égale, le jeu le plus joué passe devant (100 votes → ×0,85 ; 10 000 et plus → ×1).
    s *= Math.min(1, 0.7 + 0.075 * Math.log10((j.votes || 0) + 1));
    const raison = [...communs].sort((a, b) => poidsTag(b) - poidsTag(a)).slice(0, 3).map(libelleTag);
    out.push({ id: j.id, titre: j.titre, annee: j.annee, url: j.url, note: j.note, votes: j.votes, score: Math.round(s * 100) / 100, raison: [...new Set(raison)] });
  }
  return out.sort((a, b) => b.score - a.score).filter(x => x.score >= 0.2).slice(0, n);
}

// Saisie semi-automatique : titres qui commencent par la saisie d'abord, jeux de base avant extensions, sans doublon.
function classerSuggestions(q, candidats, n = 8) {
  const k = normalize(q);
  const rang = c => (normalize(c.title).startsWith(k) ? 0 : 2) + (c.type === 'basegame' ? 0 : 1);
  const vus = new Set();
  return (candidats || []).map((c, i) => ({ c, i })).sort((a, b) => rang(a.c) - rang(b.c) || a.i - b.i)
    .map(x => x.c.title).filter(t => !vus.has(t) && vus.add(t)).slice(0, n);
}

// Code-barres : un EAN-8/13 ou UPC-A (8 à 14 chiffres).
const estEan = s => /^\d{8,14}$/.test(String(s || '').trim());

// Vidéos YouTube de la recherche d'une chaîne (youtube.com/@chaine/search?query=…, sans clé d'API) :
// les vidéos sont dans le JSON « var ytInitialData = {…}; » de la page (objets videoRenderer, parcourus récursivement).
function parseYtVideos(html) {
  const m = String(html || '').match(/var ytInitialData = (\{[\s\S]*?\});<\/script>/);
  if (!m) return [];
  const out = [];
  const vus = new Set();
  (function walk(o) {
    if (!o || typeof o !== 'object') return;
    const v = o.videoRenderer;
    if (v && v.videoId && !vus.has(v.videoId)) {
      vus.add(v.videoId);
      out.push({ id: v.videoId, titre: ((v.title && v.title.runs) || []).map(r => r.text).join(''), duree: (v.lengthText && v.lengthText.simpleText) || null,
        url: 'https://www.youtube.com/watch?v=' + v.videoId, image: `https://i.ytimg.com/vi/${v.videoId}/mqdefault.jpg` });
    }
    for (const k in o) walk(o[k]);
  })(JSON.parse(m[1]));
  return out;
}
// Le titre de la vidéo désigne-t-il ce jeu ? Égalité (accents, casse et ponctuation ignorés), à une lettre près dès 5 lettres.
function aUneLettre(a, b) {
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && a[i] === b[i]) i++;
  return a.slice(i + 1) === b.slice(i + 1) || a.slice(i) === b.slice(i + 1) || a.slice(i + 1) === b.slice(i);
}
const memeTitre = (a, titres) => { const n = normalize(a); return !!n && titres.some(t => { const k = normalize(t); return k && (n === k || (k.length >= 5 && aUneLettre(n, k))); }); };
// Ludochrono (chaîne Ludovox) : « Ludochrono - Res Arcana » ; « Ludochrono - Res Arcana Duo » n'est pas Res Arcana.
function pickLudochrono(videos, titres) {
  return (videos || []).find(v => { const m = v.titre.match(/^\s*ludo\s*chrono\s*[-–:|]\s*(.+)$/i); return m && memeTitre(m[1], titres); }) || null;
}
// Le Chalet (chaîne Un Monde de jeux) : « Zénith, on explique et on joue avec … », « Trail Again On explique et on joue ».
function pickChalet(videos, titres) {
  return (videos || []).find(v => { const m = v.titre.match(/^(.+?)[\s,.!:-]*on (vous )?explique/i); return m && memeTitre(m[1], titres); }) || null;
}

if (typeof module !== 'undefined' && module.exports) {
  if (typeof normalize === 'undefined') global.normalize = require('./match.js').normalize;
  if (typeof bggFr === 'undefined') global.bggFr = require('./bgg.js').bggFr;
  module.exports = { parseLinkedItems, pickExtensions, pickTopMeca, geekItemTags, linkedItemsUrl, preselection, scoreJumeaux, classerSuggestions, estEan, parseYtVideos, pickLudochrono, pickChalet };
}


// ---- n8n/code/outils.body.js
